    4×2 DataFrame
     Row │ x      y
         │ Int64  Int64
    ─────┼──────────────
       1 │     1    121
       2 │     4    144
       3 │     9    169
       4 │    16    196

    julia> mapcols(x -> x.^2, df, cols=r"y")
    4×2 DataFrame
     Row │ x      y
         │ Int64  Int64
    ─────┼──────────────
       1 │     1    121
       2 │     2    144
       3 │     3    169
       4 │     4    196
    ```
    """
    if cols is All():
        cols = _names(df)
    else:
        cols = _select_cols(df, cols)
    col_indices = _name_to_col(df, cols)
    ncols = length(col_indices)
    new_cols = Vector{AbstractVector}(undef, ncols)
    for i in 1:ncols
        col_i = col_indices[i]
        new_cols[i] = f(df[!, col_i])
    end
    return DataFrame(new_cols, Index(_names(df)[col_indices]))
