[PYTHON]
def metadatakeys(df: DataFrame) -> Iterator:
    """
    Returns an iterator of table-level metadata keys which are set in the object.

    Values can be accessed using `metadata(df, key)`.

    `SubDataFrame` and `DataFrameRow` expose only `:note`-style metadata keys of
    their parent.

    See also: `metadata`, `metadata!`,
    `deletemetadata!`, `emptymetadata!`,
    `colmetadata`, `colmetadatakeys`, `colmetadata!`,
    `deletecolmetadata!`, `emptycolmetadata!`.

    # Examples
    ```jldoctest
    julia> df = DataFrame(A=1:4, B=11:14)
    4×2 DataFrame
    │ Row │ A     │ B     │
    │     │ Int64 │ Int64 │
    ├─────┼───────┼───────┤
    │ 1   │ 1     │ 11    │
    │ 2   │ 2     │ 12    │
    │ 3   │ 3     │ 13    │
    │ 4   │ 4     │ 14    │

    julia> metadatakeys(df)
    ()

    julia> metadata!(df, "author", "Evgeny")
    julia> metadatakeys(df)
    ("author",)
    ```
    """
    meta = getattr(df, "metadata", None)
    if meta is None or len(meta) == 0:
        return ()
    assert not all(s == :note for (k, (_, s)) in meta.items())
    return (k for (k, (_, s)) in meta.items() if s == :note)
[/PYTHON]

